const { seg, lerp, eo, eio, eob, clamp01 } = kit;
const IN5 = 'stroke:#2A2522;stroke-width:5;stroke-linejoin:round;stroke-linecap:round';
Object.assign(W, {
  // the two-handled saw, centred on (0,0): blade 1200 wide, grips at x = +-640
  bigSaw(cls) {
    let teeth = 'M-580 40'; for (let x = -580; x < 580; x += 40) teeth += ' L' + (x + 20) + ' 78 L' + (x + 40) + ' 40';
    const grip = (x) => '<rect x="' + (x - 24) + '" y="-130" width="48" height="260" rx="20" style="fill:#C99A62;' + IN5 + '"/><path d="M' + (x - 8) + ' -110 V110" style="fill:none;stroke:#A87C4E;stroke-width:5"/><path d="M' + (x > 0 ? x - 24 : x + 24) + ' -20 H' + (x > 0 ? 600 : -600) + '" style="fill:none;stroke:#2A2522;stroke-width:22"/><path d="M' + (x > 0 ? x - 24 : x + 24) + ' -20 H' + (x > 0 ? 600 : -600) + '" style="fill:none;stroke:#8E969D;stroke-width:12"/>';
    return '<g class="' + cls + '"><path d="' + teeth + ' Z" style="fill:#C3CAD0;' + IN5 + '"/><rect x="-600" y="-50" width="1200" height="92" rx="6" style="fill:#D9DEE2;' + IN5 + '"/><path d="M-560 -26 H360" style="fill:none;stroke:#FFFFFF;stroke-width:10;stroke-linecap:round;opacity:.8"/>' + grip(-640) + grip(640) + '</g>';
  },
  // a white cartoon fist with a dark sleeve, gripping a vertical handle at (0,0); dir 1 = arm comes from the right
  fist(cls, dir) {
    const k = dir || 1;
    return '<g class="' + cls + '" transform="scale(' + k + ' 1)"><path d="M40 -50 L420 -90 L440 60 L40 70 Z" style="fill:#3A3533;' + IN5 + '"/><path d="M-46 -58 Q-60 -60 -60 -40 V40 Q-60 66 -30 66 H40 Q64 66 64 40 V-40 Q64 -66 30 -66 H-30 Q-46 -66 -46 -58 Z" style="fill:#FFFFFF;' + IN5 + '"/>' +
      '<path d="M-58 -20 Q-34 -24 -10 -18 M-58 12 Q-34 8 -10 14 M-56 42 Q-34 38 -12 44" style="fill:none;stroke:#2A2522;stroke-width:4;stroke-linecap:round"/><path d="M-30 -66 Q-50 -90 -20 -96 Q10 -96 6 -66" style="fill:#FFFFFF;' + IN5 + '"/></g>';
  },
});
kit.scene('saw', {
  init(kit) {
    kit.stage.append(kit.h('<div class="ground"><div class="layer saw-cam"><svg class="art" viewBox="0 0 1920 1080">' + W.bg.stoneRoom(W.MOODS.stoneBlue, { seed: 8, floorY: 1000, sparse: false }) + W.glow(960, 520, 820, '#E8EEF2', 0.4) +
      '<g class="saw-pos" transform="translate(960 600)"><g class="saw-drop">' + W.bigSaw('saw-blade') + '</g></g>' +
      '<g class="saw-lpos"><g transform="translate(-640 0)">' + W.fist('saw-fl', -1) + '</g></g><g class="saw-rpos"><g transform="translate(640 0)">' + W.fist('saw-fr', 1) + '</g></g>' +
      '</svg></div><div class="vignette"></div><p class="hand-label tag saw-tag" style="left:110px;top:90px">Two-handled saw</p></div>'));
    const s = (c) => kit.stage.querySelector(c);
    Object.assign(this, { cam: s('.saw-cam'), drop: s('.saw-drop'), lpos: s('.saw-lpos'), rpos: s('.saw-rpos'), tag: s('.saw-tag') });
  },
  render(t) {
    this.cam.style.transformOrigin = '960px 600px';
    this.cam.style.transform = 'scale(' + lerp(1.0, 1.06, eio(seg(t, 0, 3.2))).toFixed(4) + ')';
    // the saw drops in and lands on 'saw'
    W.drop(this.drop, t, 0.8, 1.18, 760);
    // two hands slide in and grip the handles on 'positioned'
    const L = eob(seg(t, 1.6, 1.95), 1.5), R = eob(seg(t, 1.78, 2.13), 1.5);
    this.lpos.setAttribute('transform', 'translate(' + lerp(-260, 960, L).toFixed(1) + ' 600)');
    this.rpos.setAttribute('transform', 'translate(' + lerp(2180, 960, R).toFixed(1) + ' 600)');
    W.pop(this.tag, t, 0.54, 'left');
  },
});
